export async function createBulkAssets(baseAsset: Omit<AssetInsert, 'tenant_id' | 'created_by' | 'asset_code'>, quantity: number, startCode: string, tenantId: string, userId: string) {
  const codes = generateSequentialCodes(startCode, quantity);

  const { data: existingAssets } = await supabase
    .from('hsse_assets')
    .select('asset_code, deleted_at')
    .eq('tenant_id', tenantId)
    .in('asset_code', codes);

  if (existingAssets && existingAssets.length > 0) {
    const duplicates = existingAssets.map(a =>
      `${a.asset_code}${a.deleted_at ? ' (deleted)' : ''}`
    ).join(', ');
    throw new Error(`Asset codes already exist: ${duplicates}. Please use a different starting code.`);
  }

  const assetsToInsert = codes.map(code => ({
    ...baseAsset,
    asset_code: code,
    tenant_id: tenantId,
    created_by: userId,
  }));

  const { data, error } = await supabase
    .from('hsse_assets')
    .insert(assetsToInsert)
    .select('id, asset_code');

  if (error) {
    if (error.code === '23505') {
      const err = new Error('ConstraintError');
      (err as any).code = '23505';
      throw err;
    }
    throw error;
  }

  return data;
}

import { supabase } from '../supabaseClient';
import type { GatePassApprover, EmployeeApprover } from '@/hooks/contractor-management/use-gate-pass-approvers';

export const getGatePassApprovers = async (scope?: "external" | "internal"): Promise<Pick<GatePassApprover, "id" | "name" | "name_ar" | "code" | "sort_order" | "user_id" | "approver_scope" | "user">[]> => {
    let query = supabase
        .from("gate_pass_approvers")
        .select(`
      id, name, name_ar, code, sort_order, user_id, approver_scope,
      user:profiles!gate_pass_approvers_user_id_fkey(id, full_name, job_title, avatar_url)
    `)
        .eq("is_active", true)
        .is("deleted_at", null)
        .order("sort_order", { ascending: true });

    if (scope) {
        query = query.or(`approver_scope.eq.${scope},approver_scope.eq.both`);
    }

    const { data, error } = await query;

    if (error) throw error;
    return (data || []).map((item: any) => ({
        ...item,
        user: item.user || null,
    }));
};

export const getEmployeeApprovers = async (tenantId: string): Promise<EmployeeApprover[]> => {
    const { data, error } = await supabase
        .from("profiles")
        .select("id, full_name, job_title")
        .eq("tenant_id", tenantId)
        .eq("is_deleted", false)
        .eq("is_active", true)
        .eq("user_type", "employee")
        .not("full_name", "is", null)
        .order("full_name", { ascending: true });

    if (error) throw error;
    return (data || []) as EmployeeApprover[];
};

export const getAllGatePassApprovers = async (): Promise<GatePassApprover[]> => {
    const { data, error } = await supabase
        .from("gate_pass_approvers")
        .select(`
      id, tenant_id, name, name_ar, code, description, is_active, sort_order, 
      user_id, approver_scope, created_at, updated_at,
      user:profiles!gate_pass_approvers_user_id_fkey(id, full_name, job_title, avatar_url)
    `)
        .is("deleted_at", null)
        .order("sort_order", { ascending: true });

    if (error) throw error;
    return (data || []).map((item: any) => ({
        ...item,
        approver_scope: item.approver_scope || "both",
        user: item.user || null,
    })) as GatePassApprover[];
};

export const createGatePassApprover = async (
    approver: {
        name: string;
        name_ar?: string;
        code: string;
        description?: string;
        is_active?: boolean;
        sort_order?: number;
        user_id?: string;
        approver_scope?: "external" | "internal" | "both";
    },
    userId: string
) => {
    const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", userId)
        .single();

    if (!profile?.tenant_id) throw new Error("Tenant not found");

    const { data, error } = await supabase
        .from("gate_pass_approvers")
        .insert({
            ...approver,
            tenant_id: profile.tenant_id,
            approver_scope: approver.approver_scope || "both",
        })
        .select()
        .single();

    if (error) throw error;
    return data;
};

export const updateGatePassApprover = async (
    id: string,
    updates: Partial<GatePassApprover>
) => {
    const { user, ...updateData } = updates as any;

    const { data, error } = await supabase
        .from("gate_pass_approvers")
        .update(updateData)
        .eq("id", id)
        .select()
        .single();

    if (error) throw error;
    return data;
};

export const deleteGatePassApprover = async (id: string) => {
    const { error } = await supabase
        .from("gate_pass_approvers")
        .update({ deleted_at: new Date().toISOString() })
        .eq("id", id);

    if (error) throw error;
};

import { supabase } from '../supabaseClient';

export interface RenewGatePassResult {
    success: boolean;
    new_status?: string;
    renewal_expires_at?: string;
    renewal_count?: number;
    error?: string;
}

export interface ResubmitGatePassResult {
    success: boolean;
    new_status?: string;
    start_date?: string;
    end_date?: string;
    error?: string;
}

export const renewGatePass = async (gatePassId: string, userId: string): Promise<RenewGatePassResult> => {
    const { data, error } = await (supabase.rpc as Function)('renew_expired_gate_pass', {
        p_gate_pass_id: gatePassId,
        p_user_id: userId,
    });

    if (error) {
        throw new Error(error.message);
    }

    const result = data as unknown as RenewGatePassResult;
    if (!result.success) {
        throw new Error(result.error || "Failed to renew gate pass");
    }

    return result;
};

export const resubmitGatePass = async (
    gatePassId: string,
    userId: string,
    startDate: string,
    endDate: string,
    timeWindowStart?: string,
    timeWindowEnd?: string
): Promise<ResubmitGatePassResult> => {
    const { data, error } = await (supabase.rpc as Function)('resubmit_gate_pass', {
        p_gate_pass_id: gatePassId,
        p_user_id: userId,
        p_new_start_date: startDate,
        p_new_end_date: endDate,
        p_new_time_window_start: timeWindowStart || null,
        p_new_time_window_end: timeWindowEnd || null,
    });

    if (error) {
        throw new Error(error.message);
    }

    const result = data as unknown as ResubmitGatePassResult;
    if (!result.success) {
        throw new Error(result.error || "Failed to resubmit gate pass");
    }

    return result;
};

import { supabase } from '../supabaseClient';
import type { GatePassDetailData, GatePassItem, GatePassPhoto, GatePassApproverProfile } from '@/hooks/contractor-management/use-gate-pass-details';

export const getGatePassDetails = async (passId: string, tenantId: string): Promise<GatePassDetailData | null> => {
    const { data: passData, error: passError } = await supabase
        .from("material_gate_passes")
        .select(`
      id, reference_number, project_id, company_id, pass_type, material_description,
      quantity, vehicle_plate, driver_name, driver_mobile, pass_date,
      start_date, end_date, renewal_count, renewed_by, renewed_at, renewal_expires_at,
      time_window_start, time_window_end, status, requested_by,
      contractor_approved_by, contractor_approved_at, contractor_approval_notes,
      pm_approved_by, pm_approved_at, pm_notes,
      club_mgmt_ack_by, club_mgmt_ack_at, club_mgmt_ack_notes,
      security_approved_by, security_approved_at, security_approval_notes,
      safety_approved_by, safety_approved_at, safety_notes,
      rejected_by, rejected_at, rejection_reason,
      guard_verified_by, guard_verified_at, entry_time, exit_time, created_at,
      is_internal_request, approval_from_id, qr_code_token, qr_generated_at,
      is_public_request, public_requester_name, public_requester_phone,
      public_requester_email, public_requester_company,
      project:contractor_projects(project_name, company:contractor_companies(company_name)),
      company:contractor_companies(company_name)
    `)
        .eq("id", passId)
        .eq("tenant_id", tenantId)
        .is("deleted_at", null)
        .single();

    if (passError) throw passError;
    if (!passData) return null;

    const passDataExt = passData as typeof passData & {
        club_mgmt_ack_by?: string | null;
        club_mgmt_ack_at?: string | null;
        club_mgmt_ack_notes?: string | null;
    };

    const profileIds = [
        passDataExt.requested_by,
        passDataExt.contractor_approved_by,
        passDataExt.pm_approved_by,
        passDataExt.club_mgmt_ack_by,
        passDataExt.security_approved_by,
        passDataExt.safety_approved_by,
        passDataExt.rejected_by,
        passDataExt.guard_verified_by,
        passDataExt.approval_from_id,
    ].filter(Boolean) as string[];

    let profiles: GatePassApproverProfile[] = [];
    if (profileIds.length > 0) {
        const { data } = await supabase
            .from("profiles")
            .select("id, full_name, avatar_url")
            .in("id", profileIds);
        profiles = data || [];
    }

    const profileMap = new Map((profiles || []).map(p => [p.id, p]));

    const requesterProfile = passDataExt.is_public_request
        ? {
            id: 'public',
            full_name: passDataExt.public_requester_name || 'Public User',
            avatar_url: null,
            email: passDataExt.public_requester_email,
            phone: passDataExt.public_requester_phone
        } as any
        : (profileMap.get(passDataExt.requested_by) || null);

    return {
        ...passDataExt,
        requester: requesterProfile,
        contractor_approver: passDataExt.contractor_approved_by ? profileMap.get(passDataExt.contractor_approved_by) || null : null,
        pm_approver: passDataExt.pm_approved_by ? profileMap.get(passDataExt.pm_approved_by) || null : null,
        club_mgmt_acker: passDataExt.club_mgmt_ack_by ? profileMap.get(passDataExt.club_mgmt_ack_by) || null : null,
        security_approver: passDataExt.security_approved_by ? profileMap.get(passDataExt.security_approved_by) || null : null,
        safety_approver: passDataExt.safety_approved_by ? profileMap.get(passDataExt.safety_approved_by) || null : null,
        rejector: passDataExt.rejected_by ? profileMap.get(passDataExt.rejected_by) || null : null,
        guard: passDataExt.guard_verified_by ? profileMap.get(passDataExt.guard_verified_by) || null : null,
        approval_from: passDataExt.approval_from_id ? profileMap.get(passDataExt.approval_from_id) || null : null,
    } as GatePassDetailData;
};

