export const getGatePassPhotos = async (passId: string, tenantId: string, isPublic: boolean = false): Promise<GatePassPhoto[]> => {
    if (isPublic) {
        const { data: publicItems, error: pubError } = await supabase
            .from("public_gate_pass_items")
            .select("id, gate_pass_id, photo_storage_path, item_name, created_at")
            .eq("gate_pass_id", passId)
            .not("photo_storage_path", "is", null)
            .is("deleted_at", null);

        if (pubError) throw pubError;

        const photosWithUrls: GatePassPhoto[] = [];
        await Promise.all(
            (publicItems || []).map(async (item) => {
                if (!item.photo_storage_path) return;
                const { data: signedData } = await supabase.storage
                    .from("public-gate-pass-photos")
                    .createSignedUrl(item.photo_storage_path, 3600);

                if (signedData?.signedUrl) {
                    photosWithUrls.push({
                        id: item.id,
                        gate_pass_id: item.gate_pass_id,
                        item_id: item.id,
                        storage_path: item.photo_storage_path,
                        file_name: item.item_name || "photo",
                        file_size: null,
                        mime_type: null,
                        uploaded_by: null,
                        created_at: item.created_at,
                        signedUrl: signedData.signedUrl,
                    });
                }
            })
        );
        return photosWithUrls;
    }

    const { data: itemPhotos, error: itemError } = await supabase
        .from("gate_pass_item_photos")
        .select("id, gate_pass_id, item_id, storage_path, file_name, file_size, mime_type, uploaded_by, created_at")
        .eq("gate_pass_id", passId)
        .eq("tenant_id", tenantId)
        .is("deleted_at", null)
        .order("created_at", { ascending: true });

    if (itemError) throw itemError;

    const { data: generalPhotos, error: generalError } = await supabase
        .from("gate_pass_photos")
        .select("id, gate_pass_id, storage_path, file_name, file_size, mime_type, uploaded_by, created_at")
        .eq("gate_pass_id", passId)
        .eq("tenant_id", tenantId)
        .is("deleted_at", null)
        .order("created_at", { ascending: true });

    if (generalError) throw generalError;

    const allPhotos: GatePassPhoto[] = [
        ...(itemPhotos || []),
        ...(generalPhotos || []).map(p => ({ ...p, item_id: null }))
    ];

    const bucketName = "gate-pass-photos";
    const photosWithUrls: GatePassPhoto[] = [];
    await Promise.all(
        allPhotos.map(async (photo) => {
            const { data: signedData } = await supabase.storage
                .from(bucketName)
                .createSignedUrl(photo.storage_path, 3600);

            if (signedData?.signedUrl) {
                photosWithUrls.push({
                    ...photo,
                    signedUrl: signedData.signedUrl,
                });
            }
        })
    );

    return photosWithUrls;
};

export interface GuardGateActionResult {
    success: boolean;
    action: 'entry' | 'exit';
    timestamp: string;
    passReference: string;
    denialReason?: string;
}

export interface GateActionAuditData {
    action: 'gate_pass_entry' | 'gate_pass_exit' | 'gate_pass_denied';
    passId: string;
    passReference: string;
    result: 'success' | 'denied';
    reason?: string;
    validationMethod: 'qr_scan' | 'manual_entry';
    metadata?: Record<string, unknown>;
}

export async function logGateAudit(
    data: GateActionAuditData,
    tenantId: string,
    userId: string,
    userName: string | null
): Promise<void> {
    try {
        await supabase.from('security_audit_logs').insert({
            tenant_id: tenantId,
            actor_id: userId,
            actor_name: userName,
            action: data.action,
            action_category: 'gate_control',
            entity_type: 'material_gate_pass',
            entity_id: data.passId,
            entity_identifier: data.passReference,
            result: data.result,
            result_reason: data.reason,
            metadata: {
                validation_method: data.validationMethod,
                ...data.metadata,
            },
        });
    } catch (error) {
        console.error('Failed to log gate audit:', error);
    }
}

export const processGuardGateAction = async (
    passId: string,
    passReference: string,
    action: 'entry' | 'exit',
    validationMethod: 'qr_scan' | 'manual_entry',
    tenantId: string,
    userId: string,
    userName: string | null,
    metadata?: Record<string, unknown>
): Promise<GuardGateActionResult> => {
    const now = new Date().toISOString();
    let error: any = null;

    const { data: passData, error: fetchError } = await supabase
        .from('material_gate_passes')
        .select('vehicle_plate, driver_name, driver_mobile, material_description, pass_type, start_date, end_date')
        .eq('id', passId)
        .single();

    if (fetchError || !passData) {
        error = fetchError || new Error(`Gate pass with ID ${passId} not found.`);
    }

    if (!error && passData) {
        const pt = passData.pass_type as string;

        if (pt === 'in' && action === 'exit') {
            await logGateAudit({
                action: 'gate_pass_denied',
                passId,
                passReference,
                result: 'denied',
                reason: 'Exit not allowed on entry-only pass',
                validationMethod,
                metadata,
            }, tenantId, userId, userName);
            throw new Error('This is an Entry-only pass. Exit is not allowed.');
        }

        if (pt === 'out' && action === 'entry') {
            await logGateAudit({
                action: 'gate_pass_denied',
                passId,
                passReference,
                result: 'denied',
                reason: 'Entry not allowed on exit-only pass',
                validationMethod,
                metadata,
            }, tenantId, userId, userName);
            throw new Error('This is an Exit-only pass. Entry is not allowed.');
        }

        const today = new Date().toISOString().split('T')[0];
        const startDate = passData.start_date || today;
        const endDate = passData.end_date || startDate;

        if (today < startDate || today > endDate) {
            await logGateAudit({
                action: 'gate_pass_denied',
                passId,
                passReference,
                result: 'denied',
                reason: `Access attempt outside allowed date range (${startDate} to ${endDate})`,
                validationMethod,
                metadata,
            }, tenantId, userId, userName);
            throw new Error(`Gate pass is only valid from ${startDate} to ${endDate}`);
        }
    }

    if (!error && passData && action === 'entry') {
        const { error: insertError } = await supabase
            .from('gate_entry_logs')
            .insert({
                tenant_id: tenantId,
                guard_id: userId,
                entry_type: 'vehicle',
                person_name: passData.driver_name || 'Driver',
                mobile_number: passData.driver_mobile,
                car_plate: passData.vehicle_plate,
                purpose: passData.material_description
                    ? `Material: ${passData.material_description.length > 50
                        ? `${passData.material_description.substring(0, 50)}...`
                        : passData.material_description}`
                    : 'Material Transport',
                notes: `Gate Pass: ${passReference}`,
                entry_time: now,
                access_type: 'entry',
                validation_status: 'valid',
                material_gate_pass_id: passId,
            });

        error = insertError;
    } else if (!error && passData && action === 'exit') {
        const { data: validation, error: validationError } = await supabase.rpc('validate_gate_pass_exit', {
            p_gate_pass_id: passId,
            p_exit_vehicle_plate: (metadata as Record<string, unknown>)?.exit_vehicle_plate as string || passData.vehicle_plate,
            p_exit_driver_name: (metadata as Record<string, unknown>)?.exit_driver_name as string || passData.driver_name
        });

        if (validationError) {
            await logGateAudit({
                action: 'gate_pass_denied',
                passId,
                passReference,
                result: 'denied',
                reason: validationError.message || 'Exit validation failed',
                validationMethod,
                metadata,
            }, tenantId, userId, userName);
            throw new Error(validationError.message || 'Exit validation failed');
        }

        const validationResult = validation as {
            allowed: boolean;
            reason?: string;
            expected_vehicle?: string;
            provided_vehicle?: string;
            expected_driver?: string;
            provided_driver?: string;
            mismatch_type?: string;
        } | null;

        if (validationResult && !validationResult.allowed) {
            const reason = validationResult.reason || 'Exit validation failed';

            await logGateAudit({
                action: 'gate_pass_denied',
                passId,
                passReference,
                result: 'denied',
                reason: reason,
                validationMethod,
                metadata: {
                    ...metadata,
                    expected_vehicle: validationResult.expected_vehicle,
                    provided_vehicle: validationResult.provided_vehicle,
                    expected_driver: validationResult.expected_driver,
                    provided_driver: validationResult.provided_driver,
                    mismatch_type: validationResult.mismatch_type,
                },
            }, tenantId, userId, userName);

            throw new Error(reason);
        }

        let openLog: { id: string } | null = null;

        const { data: fkLogs } = await supabase
            .from('gate_entry_logs')
            .select('id')
            .eq('tenant_id', tenantId)
            .eq('material_gate_pass_id', passId)
            .is('exit_time', null)
            .order('entry_time', { ascending: false })
            .limit(1);

        openLog = fkLogs?.[0] || null;

        if (!openLog && passData.vehicle_plate) {
            const { data: plateLogs } = await supabase
                .from('gate_entry_logs')
                .select('id')
                .eq('tenant_id', tenantId)
                .eq('car_plate', passData.vehicle_plate)
                .is('exit_time', null)
                .order('entry_time', { ascending: false })
                .limit(1);
            openLog = plateLogs?.[0] || null;
        }

        if (openLog) {
            const { error: updateError } = await supabase
                .from('gate_entry_logs')
                .update({ exit_time: now })
                .eq('id', openLog.id);
            error = updateError;
        } else {
            console.warn('No entry log found for pass exit. Updating pass directly.');
            const { error: passError } = await supabase
                .from('material_gate_passes')
                .update({
                    exit_time: now,
                    guard_verified_by: userId,
                    guard_verified_at: now,
                    status: 'completed'
                })
                .eq('id', passId);
            error = passError;
        }
    }

    if (error) {
        await logGateAudit(
            {
                action: `gate_pass_${action}` as 'gate_pass_entry' | 'gate_pass_exit',
                passId,
                passReference,
                result: 'denied',
                reason: error.message,
                validationMethod,
                metadata,
            },
            tenantId,
            userId,
            userName
        );
        throw error;
    }

    await logGateAudit(
        {
            action: `gate_pass_${action}` as 'gate_pass_entry' | 'gate_pass_exit',
            passId,
            passReference,
            result: 'success',
            validationMethod,
            metadata,
        },
        tenantId,
        userId,
        userName
    );

    return {
        success: true,
        action,
        timestamp: now,
        passReference,
    };
};

function formatPassData(pass: any) {
    return {
        id: pass.id,
        reference_number: pass.reference_number,
        pass_type: pass.pass_type,
        material_description: pass.material_description,
        quantity: pass.quantity,
        vehicle_plate: pass.vehicle_plate,
        driver_name: pass.driver_name,
        driver_mobile: pass.driver_mobile,
        pass_date: pass.pass_date,
        start_date: pass.start_date || pass.pass_date,
        end_date: pass.end_date || pass.pass_date,
        time_window_start: pass.time_window_start,
        time_window_end: pass.time_window_end,
        status: pass.status,
        entry_time: pass.entry_time,
        exit_time: pass.exit_time,
        project_name: pass.project?.project_name || '',
        company_name: pass.project?.company?.company_name || '',
    };
}

export const verifyPassByReference = async (referenceNumber: string, tenantId: string) => {
    const normalizedRef = referenceNumber.trim().toUpperCase();
    const today = new Date().toISOString().split('T')[0];

    const { data: pass, error } = await supabase
        .from('material_gate_passes')
        .select(`
      id, reference_number, pass_type, pass_date, start_date, end_date,
      time_window_start, time_window_end,
      material_description, quantity, vehicle_plate, driver_name, driver_mobile,
      status, entry_time, exit_time,
      project:contractor_projects(project_name, company:contractor_companies(company_name))
    `)
        .eq('tenant_id', tenantId)
        .ilike('reference_number', normalizedRef)
        .is('deleted_at', null)
        .single();

    if (error || !pass) {
        return {
            is_valid: false,
            errors: ['Gate pass not found with this reference number'],
            warnings: [],
        };
    }

    if (pass.status !== 'approved' && pass.status !== 'used') {
        const statusMessages: Record<string, string> = {
            pending_contractor_approval: 'Gate pass pending contractor consultant approval',
            pending_club_mgmt_ack: 'Gate pass pending Golf Club Management acknowledgment',
            pending_dept_ack: 'Gate pass pending department acknowledgment',
            pending_dept_approval: 'Gate pass pending department approval',
            pending_security_approval: 'Gate pass pending security approval',
            pending_pm_approval: 'Gate pass pending PM approval',
            pending_safety_approval: 'Gate pass pending safety approval',
            rejected: 'Gate pass has been rejected',
            cancelled: 'Gate pass has been cancelled',
            completed: 'Gate pass already completed',
            expired: 'Gate pass has expired',
        };
        return {
            is_valid: false,
            errors: [statusMessages[pass.status] || 'Gate pass not yet fully approved'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    const startDate = pass.start_date || pass.pass_date;
    const endDate = pass.end_date || pass.pass_date;

    if (today < startDate) {
        return {
            is_valid: false,
            errors: ['Gate pass is for a future date'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    if (today > endDate) {
        return {
            is_valid: false,
            errors: ['Gate pass has expired'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    const warnings: string[] = [];
    if (pass.time_window_start && pass.time_window_end) {
        const now = new Date();
        const currentTime = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
        if (currentTime < pass.time_window_start || currentTime > pass.time_window_end) {
            return {
                is_valid: false,
                errors: [`Gate pass valid only between ${pass.time_window_start} - ${pass.time_window_end}`],
                warnings: [],
                pass: formatPassData(pass),
            };
        }
    }

    const passType = pass.pass_type as string;
    let allowedAction: 'entry' | 'exit' | 'both' = 'both';

    if (passType === 'in') {
        allowedAction = 'entry';
    } else if (passType === 'out') {
        allowedAction = 'exit';
    }

    if (passType === 'in' && pass.entry_time) {
        return {
            is_valid: false,
            errors: ['Entry has already been recorded for this entry-only pass'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    if (passType === 'out' && pass.exit_time) {
        return {
            is_valid: false,
            errors: ['Exit has already been recorded for this exit-only pass'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    if (pass.entry_time && pass.exit_time) {
        return {
            is_valid: false,
            errors: ['Gate pass already completed'],
            warnings: [],
            pass: formatPassData(pass),
        };
    }

    if (allowedAction === 'entry') {
        warnings.push('Entry-only pass ΓÇö exit is not permitted');
    } else if (allowedAction === 'exit') {
        warnings.push('Exit-only pass ΓÇö entry is not permitted');
    }

    return {
        is_valid: true,
        errors: [],
        warnings,
        pass: formatPassData(pass),
        allowed_action: allowedAction,
    };
};

import { supabase } from '../supabaseClient';
import { compressImage } from "@/lib/upload-utils";
import type {
  MaterialGatePass,
  GatePassFilters,
  CreateGatePassData
} from '@/hooks/contractor-management/use-material-gate-passes';

export const getMaterialGatePasses = async (tenantId: string, filters: GatePassFilters = {}): Promise<MaterialGatePass[]> => {
  let query = supabase
    .from("material_gate_passes")
    .select(`
      id, reference_number, project_id, company_id, pass_type, material_description,
      quantity, vehicle_plate, driver_name, driver_mobile, pass_date, start_date, end_date,
      time_window_start, time_window_end, status, requested_by,
      pm_approved_by, pm_approved_at, pm_notes,
      safety_approved_by, safety_approved_at, safety_notes,
      rejected_by, rejected_at, rejection_reason,
      guard_verified_by, guard_verified_at, entry_time, exit_time, created_at,
      is_internal_request, approval_from_id,
      renewal_count, renewed_by, renewed_at, renewal_expires_at,
      project:contractor_projects(project_name, company:contractor_companies(company_name)),
      company:contractor_companies(company_name),
      requester:profiles!requested_by(full_name)
    `)
    .eq("tenant_id", tenantId)
    .is("deleted_at", null)
    .order("created_at", { ascending: false });

  if (filters.projectId) query = query.eq("project_id", filters.projectId);
  if (filters.companyId) query = query.eq("company_id", filters.companyId);
  if (filters.status) query = query.eq("status", filters.status);
  if (filters.passDate) query = query.eq("pass_date", filters.passDate);
  if (filters.search) {
    query = query.or(`reference_number.ilike.%${filters.search}%,material_description.ilike.%${filters.search}%,vehicle_plate.ilike.%${filters.search}%`);
  }

  const { data, error } = await query;
  if (error) throw error;
  return (data || []) as MaterialGatePass[];
};

export const getPendingGatePassApprovals = async (tenantId: string, userId: string): Promise<MaterialGatePass[]> => {
  // Step 1: Get user's roles
  const { data: userRoles } = await supabase
    .from("user_role_assignments")
    .select("roles(code)")
    .eq("user_id", userId)
    .eq("tenant_id", tenantId);

  const roleCodes = (userRoles || [])
    .map((r: { roles: { code: string } | null }) => r.roles?.code)
    .filter(Boolean) as string[];

  // Step 2: Determine which statuses this user can approve based on roles
  const allowedStatuses: string[] = [];

  if (roleCodes.includes("security_supervisor") || roleCodes.includes("security_manager")) allowedStatuses.push("pending_security_approval");
  if (roleCodes.includes("contractor_consultant")) allowedStatuses.push("pending_contractor_approval");
  if (roleCodes.includes("department_representative") || roleCodes.includes("department_manager")) {
    allowedStatuses.push("pending_dept_approval", "pending_club_mgmt_ack", "pending_dept_ack");
  }
  if (roleCodes.includes("admin")) {
    allowedStatuses.push("pending_dept_approval", "pending_contractor_approval", "pending_club_mgmt_ack", "pending_security_approval", "pending_dept_ack", "pending_pm_approval", "pending_safety_approval");
  }

  if (allowedStatuses.length === 0) return [];

  const uniqueStatuses = [...new Set(allowedStatuses)];

  // Step 3: Fetch passes
  const { data: passes, error } = await supabase
    .from("material_gate_passes")
    .select(`
      id, reference_number, project_id, company_id, pass_type, material_description,
      quantity, vehicle_plate, driver_name, driver_mobile, pass_date,
      time_window_start, time_window_end, status, requested_by, created_at,
      is_internal_request, approval_from_id,
      is_public_request, public_requester_name, public_requester_phone,
      public_requester_email, public_requester_company,
      project:contractor_projects(project_name, company:contractor_companies(company_name)),
      company:contractor_companies(company_name),
      requester:profiles!requested_by(full_name),
      approval_from:profiles!material_gate_passes_approval_from_id_fkey(full_name)
    `)
    .eq("tenant_id", tenantId)
    .is("deleted_at", null)
    .in("status", uniqueStatuses)
    .or(`requested_by.neq.${userId},requested_by.is.null`)
    .order("created_at", { ascending: false });

  if (error) throw error;

  // Step 4: Apply additional filtering
  const filteredPasses = (passes || []).filter((pass) => {
    const p = pass as unknown as MaterialGatePass;
    if (p.is_internal_request && p.status === "pending_dept_approval") {
      return p.approval_from_id === userId;
    }
    return true;
  });

  return filteredPasses as unknown as MaterialGatePass[];
};

