export const startInvestigation = async (incidentId: string, investigatorId: string, assignmentNotes: string | undefined, userId: string, tenantId: string) => {
  const { error: incidentError } = await supabase
    .from('incidents')
    .update({
      status: 'investigation_in_progress',
      investigation_started_at: new Date().toISOString(),
    })
    .eq('id', incidentId);

