  const { error: investigationError } = await supabase
    .from('investigations')
    .upsert({
      incident_id: incidentId,
      tenant_id: tenantId,
      investigator_id: investigatorId,
      assigned_at: new Date().toISOString(),
      assigned_by: userId,
      assignment_notes: assignmentNotes || null,
