export const createCorrectiveAction = async (
  action: {
    incident_id: string;
    title: string;
    description?: string;
    assigned_to?: string;
    responsible_department_id?: string;
    start_date?: string;
    due_date?: string;
    priority?: string;
    action_type?: string;
    category?: string;
    linked_root_cause_id?: string;
    linked_cause_type?: string;
  },
  tenantId: string,
  userId: string
) => {
  const { data: incident } = await supabase
    .from('incidents')
    .select('branch_id, event_type')
    .eq('id', action.incident_id)
    .single();

  const { data, error } = await supabase
    .from('corrective_actions')
    .insert({
      ...action,
      tenant_id: tenantId,
      branch_id: incident?.branch_id || null,
      status: 'assigned',
    })
    .select()
    .single();

  if (error) throw error;

  await supabase.from('incident_audit_logs').insert({
    incident_id: action.incident_id,
    tenant_id: tenantId,
    actor_id: userId,
    action: 'action_created',
    new_value: { action_id: data.id, title: action.title },
  });

  return data;
};

